// PIR hareket sensörü: hareket algılanınca LED yanar
const int PIR = 2;
const int LED = 8;

void setup() {
  pinMode(PIR, INPUT);
  pinMode(LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  if (digitalRead(PIR) == HIGH) {
    digitalWrite(LED, HIGH);
    Serial.println("Hareket var");
  } else {
    digitalWrite(LED, LOW);
  }
  delay(100);
}
